'use strict';

const path=require('node:path');
const {snapshotOwnedGraph,compareOwnedGraphSnapshot}=
  require('./owned-source-graph-mutation.cjs');
const {sourceZoneSnapshot,zoneSnapshotDigest}=
  require('./source-zone-checkpoint.cjs');

/**
 * Read-only full-own-descriptor boundary witness around one original real bot
 * decision, including cyclic State object topology and Card own properties.
 * No additional hypothetical action is generated by the observer.
 *
 * @param {Function} BotClass
 * @param {number} ordinal
 * @returns {{report:object,restore:()=>void}}
 */
function observeSourceGraphDecision(BotClass,ordinal) {
  if(!Number.isSafeInteger(ordinal)||ordinal<1) {
    throw new RangeError('Expected positive bot decision ordinal');
  }
  const proto=BotClass.prototype;
  const original=Object.getOwnPropertyDescriptor(proto,'decodeNextAction');
  if(typeof original?.value!=='function') {
    throw new TypeError('Expected own bot decision method');
  }
  const report={
    protocol:'live-source-owned-descriptor-decision-boundary-v1',
    ordinal,decisions:0,witness:null
  };
  function monitored(state) {
    const n=++report.decisions;
    if(n!==ordinal)return original.value.call(this,state);
    const snap=snapshotOwnedGraph(state);
    const pre=sourceZoneSnapshot(state);
    let action;
    try {
      action=original.value.call(this,state);
      return action;
    } finally {
      report.witness={
        ordinal:n,turn:state.turn,
        actorSeat:state.activePlayer,
        entryZoneDigest:zoneSnapshotDigest(pre),
        exitZoneDigest:zoneSnapshotDigest(sourceZoneSnapshot(state)),
        chosenAction:action?.constructor?.name??'<threw>',
        chosenName:action?.name??null,
        changedGraph:compareOwnedGraphSnapshot(snap,{
          maxExamples:24
        })
      };
    }
  }
  Object.defineProperty(proto,'decodeNextAction',{
    ...original,value:monitored
  });
  return {
    report,
    restore() {
      if(proto.decodeNextAction!==monitored)throw new Error(
        'Source graph decision observer lost bot method ownership');
      Object.defineProperty(proto,'decodeNextAction',original);
    }
  };
}

/** @param {number} ordinal */
function installPinnedSourceGraphDecision(ordinal) {
  const output=path.resolve(__dirname,'../../vendor/twinleaf/ptcg-server/output');
  const {SimpleTacticsAi}=require(path.join(output,'simple-bot/simple-tactics-ai'));
  return observeSourceGraphDecision(SimpleTacticsAi,ordinal);
}
module.exports={
  observeSourceGraphDecision,installPinnedSourceGraphDecision
};
